USE pdf_extraction;
CREATE TABLE IF NOT EXISTS documents (document_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,file_name VARCHAR(255) NOT NULL,file_path VARCHAR(500),file_hash CHAR(64) NOT NULL,page_count INT UNSIGNED,file_size BIGINT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_documents_hash(file_hash)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS extraction_runs (run_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_id BIGINT UNSIGNED NOT NULL,parser_name VARCHAR(100),llm_enabled BOOLEAN NOT NULL DEFAULT FALSE,llm_provider VARCHAR(50),llm_model VARCHAR(100),status ENUM('pending','running','success','partial','failed') NOT NULL,started_at DATETIME,finished_at DATETIME,CONSTRAINT fk_runs_document FOREIGN KEY(document_id) REFERENCES documents(document_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS extracted_fields (field_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,run_id BIGINT UNSIGNED NOT NULL,field_name VARCHAR(100) NOT NULL,raw_value TEXT,normalized_value TEXT,page_number INT UNSIGNED,source_text TEXT,extraction_method ENUM('rule','table','llm','derived') NOT NULL,confidence DECIMAL(5,4),validation_status ENUM('valid','warning','invalid','missing'),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_fields_run FOREIGN KEY(run_id) REFERENCES extraction_runs(run_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS monitoring_records (record_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,run_id BIGINT UNSIGNED NOT NULL,report_title VARCHAR(255),organization VARCHAR(255),report_date DATE,period_start DATE,period_end DATE,region VARCHAR(100),sample_count INT UNSIGNED,positive_count INT UNSIGNED,positive_rate DECIMAL(10,6),alert_level VARCHAR(50),notes TEXT,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_records_run FOREIGN KEY(run_id) REFERENCES extraction_runs(run_id),CONSTRAINT chk_positive_counts CHECK(positive_count IS NULL OR sample_count IS NULL OR positive_count<=sample_count),CONSTRAINT chk_positive_rate CHECK(positive_rate IS NULL OR positive_rate BETWEEN 0 AND 1)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS validation_issues (issue_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,run_id BIGINT UNSIGNED NOT NULL,field_name VARCHAR(100),issue_type VARCHAR(100),severity ENUM('info','warning','error') NOT NULL,expected_value TEXT,actual_value TEXT,message TEXT,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_issues_run FOREIGN KEY(run_id) REFERENCES extraction_runs(run_id)) ENGINE=InnoDB;
